// TH14 synthetic aliases used by this card (see transcribe/th14/bullet-types.md).
// Native type -> target row base: 5 BALL2 -> 432, 12 ARROWHEAD -> 544.
// Appearance mapping is synthetic; source color 6 is passed unchanged.
const TH14_BALL2: int = 432;
const TH14_ARROWHEAD: int = 544;

// TH14 v1.00b st01bs::Boss2 (nonspell). Source st01bs.ecl.txt:166-212.
// Helpers: Boss2_at:214-237, Boss2_at2:239-280.
// Source t0 = timerReset(:172); the card runs the opening buffer first, so source t = card frame - opening.
// setInterrupt(0,1900,2100,"BossCard2") keeps the 2100-frame timeout as this segment's end; the
// no-DPS shell never reaches the HP threshold. HP/life, drops, stats and presentation are omitted.

const TIME_LIMIT: int = 2584;   // 120 opening + 2100 source timeout + 360 tail + 4 startup margin
const SOURCE_LIMIT: int = 2100; // source setInterrupt timeout
const OPENING_BUFFER: int = 120;

async sub boss2_at2(shot_speed: fx, interval: int, until: int) {
    // Source Boss2_at2: wait(120), then one bullet per iteration, 1200 iterations.
    wait(120);
    sh_reset(1);
    sh_sprite(1, TH14_BALL2, 6);            // etSprite(1,5,6)
    sh_ring(1, 0);                          // etAim(1,1): fixed-direction fan
    sh_aim(1, 0);
    sh_count(1, 1, 1);                      // etCount(1,1,1)
    sh_speed(1, shot_speed, 0fx);           // etSpeed(1,rank speed,1.0), one layer
    sh_dist(1, 0fx-shot_speed*4fx);         // ANIM birth retreat -4*initial speed
    for i in 0..1200 {
        if $frame >= until { return; }
        // etOffsetRad(1,RANDRAD,RANDF*32): muzzle angle then radius, in source order.
        var r_off: int = rand(65536)-32768;
        var r_rad: int = rand(65536);
        sh_offset_rad(1, r_off as angle, (r_rad as fx)*32fx/65536);
        var aim: angle = aim_player();      // ANGLE_PLAYER for this iteration
        var r_b: int = rand(65536)-32768;   // independent RANDRAD for the +-45 deg offset
        var b: angle = aim+((r_b/4) as angle);
        sh_angle(1, b, 0deg);               // etAngle(1,%B,0)
        sh_fire(1);                         // etOn(1)
        wait(interval);                     // diffWait: 60/20/10/5
    }
}

async sub boss2_at(n: int, dir: angle, until: int) {
    // Source Boss2_at: start at player angle -/+ dir*5, then a 32-shot rotating fan.
    var aim: angle = aim_player();
    var c: angle = aim;
    if dir > 0deg { c = aim-60deg; } else { c = aim+60deg; }  // %C = ANGLE_PLAYER - %B*5
    sh_reset(0);
    sh_sprite(0, TH14_ARROWHEAD, 6);        // etSprite(0,12,6)
    sh_ring(0, 0);                          // etAim(0,1): fixed-direction fan
    sh_aim(0, 0);
    sh_count(0, n, 1);                      // etCount(0,$A,1), $A = diffI(2,2,5,8)
    sh_speed(0, 1.4fx, 0fx);                // etSpeed(0,1.4,1.0), one layer
    sh_dist(0, 14.4fx);                     // etDist(0,20) + ANIM retreat -4*1.4
    for i in 0..32 {
        if $frame >= until { return; }
        sh_angle(0, c, 45deg);              // etAngle(0,%C,0.7853982)
        sh_fire(0);                         // etOn(0)
        c = c+dir;                          // %C = %C + %B
        wait(4);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source :185-187 stop old velocity/interpolation. The isolated card starts stationary at (0,128).
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    var until: int = $frame+SOURCE_LIMIT;
    var rank: int = global(GVAR_RANK);
    var n: int = 2;                 // diffI($C,2,2,5,8)
    var shot_speed: fx = 0.8fx;     // Boss2_at2 etSpeed: E/N/H/L = 0.8/0.8/1.8/2.8
    var interval: int = 60;         // Boss2_at2 wait: 60/20/10/5
    if rank == 2 { n = 5; shot_speed = 1.8fx; interval = 10; }
    if rank == 3 { n = 8; shot_speed = 2.8fx; interval = 5; }
    wait(120);                      // setInvuln(120); wait(120)
    spawn boss2_at2(shot_speed, interval, until);
    var dir: angle = 12deg;         // %D = 0.20944f (+-12 deg)
    var moved: int = 0;             // source moveRand starts only after the first 20+120 waits
    loop {
        if $frame >= until { return; }
        if moved == 0 { wait(20); } else { card_wait(20, until); }  // Boss2_936 wait(20)
        if $frame >= until { return; }
        spawn boss2_at(n, dir, until);
        dir = 0deg-dir;             // %D = %D * -1
        if moved == 0 { wait(120); } else { card_wait(120, until); }
        if $frame >= until { return; }
        card_move_rand();           // moveRand(30,4,2.0)
        moved = 1;
        card_wait(32, until);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48): native ordinary circle uses width*0.5
    set_hurtbox(20fx);  // source setHurtbox(40,40); damage disabled by training invulnerability
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 11400, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH14 st01bs::Boss2 movement only. Source moveLimit(0,128,280,96):
// final x in [-140,140], y in [80,176]; direction inner test uses center +- width/4, height/4.
// int slot0 = next-step count; fx slots 0/1 = logical unit vector (no source read uses these).
// Source wait(n) after the first moveRand must use card_wait so phase-5 advances the movement.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    // moveRand(30,4,2.0): fixed direction, speed 2*(1-k/30) for k=1..30, then 0.
    if k < 30 { speed = ((30-k)*2) as fx / 30; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 412 handler: signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad, nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int, until: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= until { return; }
        card_arm_next_step();
    }
}
